<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { app, game, gs, setMode } from '../session'
import { N, E, FLAG, HALF, CELL, isDoor } from '../core/defs'
const c = ref<HTMLCanvasElement>(); let t: any = 0, base: HTMLCanvasElement | null = null, key = ''
const paint = () => { const g = game.value, el = c.value; if (!g?.world || !el) return; const w = g.world, l = g.view.flat ? g.shownLevel : g.level, v = w.levels.get(l); const fow = app.shared.fog && app.role === 'player' ? g.exportFow() : null; const r = w.range(); const off = (l - r.min) * N * N; const k = `${l}|${w.meta.edited}|${fow ? Math.floor(performance.now() / 1500) : 0}|${w.rooms.size}`; if (k !== key || !base) { key = k; base ??= document.createElement('canvas'); base.width = base.height = N * 2; const x = base.getContext('2d')!; x.clearRect(0, 0, N * 2, N * 2); if (v) for (let z = 0; z < N; z++) for (let q = 0; q < N; q++) { const i = z * N + q, f = v.floor[i]; if (fow && fow[off + i] < 90) continue; if (!f || v.flag[i] & FLAG.solid) continue; const out = l === 0 && f === 1 && !!w.terrain; if (out && !v.room[i]) { x.fillStyle = v.flag[i] & FLAG.water ? '#1d4f7d' : '#3b7db3'; x.fillRect(q * 2, z * 2, 2, 2); continue } x.fillStyle = v.flag[i] & FLAG.lava ? '#e4572e' : v.flag[i] & FLAG.water ? '#1d4f7d' : '#e9f0f4'; x.fillRect(q * 2, z * 2, 2, 2); for (const [e, dx, dz, W, H] of [[v.eW[i], 0, 0, 1, 2], [v.eN[i], 0, 0, 2, 1]] as const) { const ty = e & 15; if (!ty || ty === E.Arch) continue; x.fillStyle = ty === E.Secret && app.role === 'player' ? '#12426b' : isDoor(ty) ? '#e4572e' : '#12426b'; x.fillRect(q * 2 + dx, z * 2 + dz, W, H) } } }
  const W = el.width = Math.round(el.clientWidth * 2), H = el.height = Math.round(el.clientHeight * 2), x = el.getContext('2d')!; if (!W) return; const f = g.view.flat ? g.view.focus : g.view.mode === 'fly' ? g.view.flyP : g.pos; const s = W / span(); x.fillStyle = '#2b6ca3'; x.fillRect(0, 0, W, H); const cs = CELL * 4 * s; x.strokeStyle = '#ffffff1f'; x.lineWidth = 1; x.beginPath(); for (let q = ((W / 2 - f.x * s) % cs + cs) % cs; q < W; q += cs) { x.moveTo(q, 0); x.lineTo(q, H) } for (let q = ((H / 2 - f.z * s) % cs + cs) % cs; q < H; q += cs) { x.moveTo(0, q); x.lineTo(W, q) } x.stroke()
  x.save(); x.imageSmoothingEnabled = false; const cx = f.x / CELL + HALF, cz = f.z / CELL + HALF; x.translate(W / 2, H / 2); x.scale(s * CELL / 2, s * CELL / 2); x.drawImage(base!, -cx * 2, -cz * 2); x.restore(); const at = (k: { x: number; z: number }) => [W / 2 + (k.x - f.x) * s, H / 2 + (k.z - f.z) * s] as const
  for (const k of w.tokens.values()) { if (Math.abs(k.y - l * 4) > 3 || (k.hidden && app.role === 'player') || (k.hp <= 0 && k.side !== 'hero')) continue; if (k.side !== 'hero' && fow && !g.visibleToParty(k.x, k.z, k.y)) continue; const [X, Y] = at(k), r = k.id === app.seat ? 8 : gs.value?.mons[k.id]?.boss ? 9 : 6; x.fillStyle = k.side === 'hero' ? '#15171b' : k.side === 'foe' ? '#e03a24' : '#f3c23c'; x.fillRect(X - r, Y - r, r * 2, r * 2); x.strokeStyle = '#fff'; x.lineWidth = k.id === app.seat ? 3 : 1.5; x.strokeRect(X - r, Y - r, r * 2, r * 2) }
  const G: any = gs.value; x.font = '600 21px "Jost Variable", sans-serif'; x.textBaseline = 'middle'; for (const p of (G?.camp?.pins ?? G?.camp?.mod?.pins ?? []) as { x: number; y: number; z: number; t: string; k: string }[]) { if (Math.abs(p.y - l * 4) > 3) continue; let [X, Y] = at(p); const out = X < 14 || Y < 14 || X > W - 14 || Y > H - 14; X = Math.max(14, Math.min(W - 14, X)); Y = Math.max(14, Math.min(H - 14, Y)); if (p.k === 'npc' && out) continue; x.fillStyle = p.k === 'npc' ? '#ffffff' : '#ffd23f'; x.beginPath(); if (p.k === 'talk' || p.k === 'npc') x.arc(X, Y, 9, 0, 7); else { x.moveTo(X, Y - 13); x.lineTo(X + 11, Y + 8); x.lineTo(X - 11, Y + 8); x.closePath() } x.fill(); x.strokeStyle = '#12305a'; x.lineWidth = 2.5; x.stroke(); if (!out && W > 260) { const tw = x.measureText(p.t).width; const L = X + 16 + tw > W - 6 ? X - 18 - tw : X + 16; x.fillStyle = '#12305acc'; x.fillRect(L - 5, Y - 14, tw + 10, 28); x.fillStyle = '#fff'; x.fillText(p.t, L, Y + 1) } }
  if (!g.view.flat) { const [a, b] = g.view.ground(); x.strokeStyle = '#fff'; x.lineWidth = 4; x.beginPath(); x.moveTo(W / 2, H / 2); x.lineTo(W / 2 + a * 26, H / 2 + b * 26); x.stroke() } }
const span = () => { const g = game.value!, k = (c.value?.clientWidth ?? 200) / 200; return (g.view.flat ? Math.max(60, Math.min(190, g.view.z * 5)) : 80) * Math.min(1.5, k) }
onMounted(() => { t = setInterval(paint, 260); paint() }); onBeforeUnmount(() => clearInterval(t)); const go = (e: MouseEvent) => { const g = game.value!, el = c.value!; if (!g.view.flat) { setMode('top'); return } const r = el.getBoundingClientRect(); const k = span() / r.width; g.centerOn(g.view.focus.x + (e.clientX - r.left - r.width / 2) * k, g.view.focus.z + (e.clientY - r.top - r.height / 2) * k, g.shownLevel) }
</script>
<template><canvas ref="c" class="mini" aria-label="Map" @click="go" /></template>
<style scoped>.mini{width:100%;display:block;cursor:pointer;pointer-events:auto;background:var(--map)}</style>
